DECLARE v_role VARCHAR2(20):='admin'; BEGIN CASE v_role WHEN 'admin' THEN
DBMS_OUTPUT.PUT_LINE('管理者'); ELSE DBMS_OUTPUT.PUT_LINE('その他'); END CASE;
END;

DECLARE CURSOR c IS SELECT name FROM users; v_name users.name%TYPE;
BEGIN OPEN c; LOOP FETCH c INTO v_name; EXIT WHEN c%NOTFOUND;
DBMS_OUTPUT.PUT_LINE(v_name); END LOOP; CLOSE c; END;

DECLARE TYPE ids_t IS TABLE OF users.id%TYPE; ids ids_t;
BEGIN SELECT id BULK COLLECT INTO ids FROM users;
DBMS_OUTPUT.PUT_LINE(ids.COUNT); END;

DECLARE v_name users.name%TYPE; BEGIN SELECT name INTO v_name FROM users WHERE
id=1; EXCEPTION WHEN NO_DATA_FOUND THEN DBMS_OUTPUT.PUT_LINE('なし');
WHEN TOO_MANY_ROWS THEN RAISE; END;
